package main

import "fmt"

func main() {
	// Backing array has cap 5; parent currently views 3 elements.
	parent := make([]int, 3, 5)
	parent[0], parent[1], parent[2] = 1, 2, 3

	// sub shares the SAME backing array: ptr advanced by 1,
	// len = 2-1 = 1, cap = 5-1 = 4. There is spare capacity.
	sub := parent[1:2]
	fmt.Println("sub      :", sub, "len", len(sub), "cap", cap(sub))

	// append fits within sub's capacity, so it writes IN PLACE
	// into the shared array at index 2 (parent[2]!), clobbering 3.
	sub = append(sub, 99)
	fmt.Println("after append sub:", sub)
	fmt.Println("parent CLOBBERED:", parent) // parent[2] is now 99

	// Fix: a three-index slice caps capacity at the view length,
	// so the next append must reallocate and cannot touch parent.
	p2 := make([]int, 3, 5)
	p2[0], p2[1], p2[2] = 1, 2, 3
	safe := p2[1:2:2] // len 1, cap 2-1 = 1 -> no spare capacity
	safe = append(safe, 99) // forces a new backing array
	fmt.Println("safe (own array):", safe)
	fmt.Println("p2 INTACT       :", p2)
}

package main

import "fmt"

func main() {
	var s []int // nil: len 0, cap 0, no backing array
	fmt.Printf("start: len=%d cap=%d nil=%v\n", len(s), cap(s), s == nil)

	prevCap := cap(s)
	for i := 0; i < 10; i++ {
		s = append(s, i) // reassign: header may change on realloc
		if cap(s) != prevCap {
			fmt.Printf("len=%2d cap=%2d  <- reallocated\n", len(s), cap(s))
			prevCap = cap(s)
		} else {
			fmt.Printf("len=%2d cap=%2d\n", len(s), cap(s))
		}
	}
}

package main

import (
	"fmt"
	"slices"
)

func firstTwoLeaky(big []int) []int {
	return big[:2] // RETAINS the entire backing array of big
}

func firstTwoSafe(big []int) []int {
	out := make([]int, 2)
	copy(out, big) // copies min(len(out), len(big)) = 2 elements
	return out      // big's huge array can now be collected
}

func main() {
	big := make([]int, 1_000_000)
	for i := range big {
		big[i] = i
	}

	leaky := firstTwoLeaky(big)
	safe := firstTwoSafe(big)
	fmt.Println("leaky:", leaky, "cap:", cap(leaky)) // cap is still ~1,000,000
	fmt.Println("safe :", safe, "cap:", cap(safe))   // cap is 2

	// Deleting from a slice of pointers: the naive idiom leaves the
	// last slot referencing freed data. slices.Delete zeroes it.
	ps := []*int{ptr(1), ptr(2), ptr(3)}
	ps = slices.Delete(ps, 1, 2) // remove index 1; tail slot is zeroed for GC
	fmt.Println("len after delete:", len(ps), "values:", *ps[0], *ps[1])
}

func ptr(v int) *int { return &v }
